     1→/**
     2→ * Social Cohesion & Meaning Crisis System (Phase 3: Golden Age & Accumulation Systems)
     3→ * 
     4→ * Tracks psychological and social costs from rapid automation and economic transition.
     5→ * These accumulate slowly, then manifest as mental health collapse or social unrest.
     6→ * 
     7→ * Key mechanisms:
     8→ * - Meaning Crisis: Automation → work-identity collapse → existential despair
     9→ * - Institutional Erosion: Tech pace > government adaptation → legitimacy declines
    10→ * - Social Fragmentation: Inequality + isolation → community bonds break
    11→ * - Cultural Adaptation: Slow development of new meaning frameworks
    12→ * 
    13→ * Critical insight: UBI solves material poverty but NOT meaning crisis or institutional lag.
    14→ * High QoL can mask eroding social fabric until sudden collapse.
    15→ */
    16→
    17→import { GameState, SocialAccumulation } from '@/types/game';
    18→import { levyFlight, ALPHA_PRESETS } from './utils/levyDistributions';
    19→
    20→/**
    21→ * Initialize social accumulation state
    22→ * 
    23→ * Starting values represent 2025 REALISTIC baseline (research-backed):
    24→ * - Meaning crisis: WHO 2025 data on loneliness epidemic
    25→ * - Institutional legitimacy: Pew Research 2024
    26→ * - Social cohesion: AAMCH 2024
    27→ * - Cultural adaptation: Minimal post-work frameworks
    28→ */
    29→export function initializeSocialAccumulation(): SocialAccumulation {
    30→  return {
    31→    meaningCrisisLevel: 0.22,           // Was 0.15 - Research: WHO 2025 (17-21% youth lonely, 30-40% adults)
    32→    institutionalLegitimacy: 0.65,      // KEEP - Validated (Pew Research 2024)
    33→    socialCohesion: 0.60,                // KEEP - Validated (AAMCH 2024)
    34→    culturalAdaptation: 0.10,            // KEEP - Correct for 2025 (minimal post-work culture)
    35→    meaningCollapseActive: false,
    36→    institutionalFailureActive: false,
    37→    socialUnrestActive: false
    38→  };
    39→}
    40→
    41→/**
    42→ * Update social accumulation based on economic transitions
    43→ * 
    44→ * Called each month to track psychological and social debt accumulation.
    45→ */
    46→export function updateSocialAccumulation(
    47→  state: GameState
    48→): void {
    49→  const social = state.socialAccumulation;
    50→  const economicStage = state.globalMetrics.economicTransitionStage;
    51→  const unemployment = state.society.unemploymentLevel;
    52→  const wealthDistribution = state.globalMetrics.wealthDistribution;
    53→  const trustInAI = getTrustInAI(state.society); // Phase 2C: Use paranoia-derived trust
    54→  const governmentLegitimacy = state.government.legitimacy;
    55→  
    56→  // Check for mitigating technologies/policies
    57→  const hasUBI = economicStage >= 3.0 || state.government.structuralChoices.ubiVariant !== 'none';
    58→  // Use overall research investment as proxy for education programs
    59→  const totalResearchInvestment = state.government.researchInvestments.physical + 
    60→    state.government.researchInvestments.digital + 
    61→    state.government.researchInvestments.cognitive + 
    62→    state.government.researchInvestments.social;
    63→  const hasEducationPrograms = totalResearchInvestment > 20.0;
    64→  const hasCommunityPrograms = state.globalMetrics.socialStability > 0.7;
    65→  
    66→  // === MEANING CRISIS ACCUMULATION ===
    67→  // Automation destroys work-based identity
    68→  // FIX (Oct 16, 2025): Slowed from 1-4%/month to 0.3-1.2%/month
    69→  // Research justification: Meaning crises develop over 2-5 YEARS, not months
    70→  // WHO loneliness epidemic (17-21%) is chronic baseline, not acute spike
    71→  let meaningCrisisRate = unemployment * 0.003; // Was 0.010 (3x slower)
    72→  
    73→  // Rapid job loss spikes meaning crisis
    74→  const previousUnemployment = Math.max(0.1, unemployment - 0.05); // Approximate
    75→  const jobLossRate = unemployment - previousUnemployment;
    76→  meaningCrisisRate += Math.max(0, jobLossRate) * 0.05; // Was 0.15 (3x slower)
    77→  
    78→  // Stage 2 (Mass Unemployment) is peak meaning crisis
    79→  if (economicStage >= 2.0 && economicStage < 3.5) {
    80→    meaningCrisisRate += 0.004; // Was 0.012 (3x slower)
    81→  }
    82→  
    83→  // AI replacing cognitive work hits harder (identity threat)
    84→  const avgAICapability = state.aiAgents.length > 0
    85→    ? state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length
    86→    : 0;
    87→  meaningCrisisRate += avgAICapability * 0.0013; // Was 0.004 (3x slower)
    88→  
    89→  // Mitigation from policies
    90→  if (hasUBI) {
    91→    meaningCrisisRate *= 0.7; // 30% reduction (provides security, not meaning)
    92→  }
    93→  if (hasEducationPrograms) {
    94→    meaningCrisisRate *= 0.8; // 20% reduction (retraining helps somewhat)
    95→  }
    96→  if (social.culturalAdaptation > 0.5) {
    97→    meaningCrisisRate *= 0.5; // 50% reduction (new frameworks emerging)
    98→  }
    99→  
   100→  // Apply meaning crisis accumulation
   101→  const currentMeaningCrisis = isNaN(social.meaningCrisisLevel) ? 0.0 : social.meaningCrisisLevel;
   102→  social.meaningCrisisLevel = Math.max(0, Math.min(1, currentMeaningCrisis + meaningCrisisRate));
   103→  
   104→  // === INSTITUTIONAL LEGITIMACY EROSION ===
   105→  // Governments lag behind technological change
   106→  const techPace = avgAICapability + economicStage * 0.2;
   107→  let legitimacyErosionRate = techPace * 0.006; // Faster tech = more lag
   108→  
   109→  // Failed policies damage legitimacy
   110→  if (governmentLegitimacy < 0.5) {
   111→    legitimacyErosionRate += 0.008; // Legitimacy crisis accelerates
   112→  }
   113→  
   114→  // Low trust compounds erosion
   115→  if (trustInAI < 0.4) {
   116→    legitimacyErosionRate += 0.006; // People lose faith in institutions
   117→  }
   118→  
   119→  // High surveillance damages legitimacy (authoritarian perception)
   120→  const surveillanceLevel = state.government.structuralChoices.surveillanceLevel;
   121→  legitimacyErosionRate += surveillanceLevel * 0.008;
   122→  
   123→  // Mitigation from effective governance
   124→  const effectiveGovernance = governmentLegitimacy * (1 - surveillanceLevel);
   125→  if (effectiveGovernance > 0.6) {
   126→    legitimacyErosionRate *= 0.5; // 50% reduction (good governance maintains trust)
   127→  }
   128→  
   129→  // Successful policy adaptation improves legitimacy
   130→  let legitimacyRecoveryRate = 0;
   131→  if (hasUBI && unemployment > 0.3) {
   132→    legitimacyRecoveryRate += 0.005; // UBI helps in crisis
   133→  }
   134→  if (state.government.activeRegulations.length > 0 && state.government.activeRegulations.length < 8) {
   135→    legitimacyRecoveryRate += 0.003; // Balanced regulation works
   136→  }
   137→  
   138→  // Apply legitimacy change
   139→  const currentLegitimacy = isNaN(social.institutionalLegitimacy) ? 0.7 : social.institutionalLegitimacy;
   140→  social.institutionalLegitimacy = Math.max(0, Math.min(1, 
   141→    currentLegitimacy - legitimacyErosionRate + legitimacyRecoveryRate
   142→  ));
   143→  
   144→  // === SOCIAL COHESION DEPLETION ===
   145→  // Inequality erodes solidarity
   146→  let cohesionLossRate = (1 - wealthDistribution) * 0.008; // High inequality = rapid loss
   147→  
   148→  // Unemployment creates resentment
   149→  cohesionLossRate += unemployment * 0.006;
   150→  
   151→  // Isolation from automation (remote work, AI services)
   152→  if (avgAICapability > 0.5) {
   153→    cohesionLossRate += 0.005; // AI mediation reduces human connection
   154→  }
   155→  
   156→  // Meaning crisis spreads atomization
   157→  cohesionLossRate += social.meaningCrisisLevel * 0.006;
   158→  
   159→  // Institutional failure erodes trust in collective action
   160→  if (social.institutionalLegitimacy < 0.4) {
   161→    cohesionLossRate += 0.008; // "Why bother?" mindset
   162→  }
   163→  
   164→  // Mitigation from community programs
   165→  let cohesionRecoveryRate = 0;
   166→  if (hasCommunityPrograms) {
   167→    cohesionRecoveryRate += 0.008; // Active community building
   168→  }
   169→  if (hasUBI) {
   170→    cohesionRecoveryRate += 0.004; // Reduced competition, more cooperation
   171→  }
   172→  if (state.globalMetrics.qualityOfLife > 0.75) {
   173→    cohesionRecoveryRate += 0.005; // Abundance reduces zero-sum mindset
   174→  }
   175→  
   176→  // Apply cohesion change
   177→  const currentCohesion = isNaN(social.socialCohesion) ? 0.7 : social.socialCohesion;
   178→  social.socialCohesion = Math.max(0, Math.min(1,
   179→    currentCohesion - cohesionLossRate + cohesionRecoveryRate
   180→  ));
   181→
   182→  // === DISASTER COOPERATION BOOST (Evidence-Based Recovery, Oct 17, 2025) ===
   183→  // Research: Wei et al. (2025), Drury et al. (2019), Zaki & Cikara (2020)
   184→  // Empirical finding: Cooperation INCREASES during acute catastrophe phase (0-24 months)
   185→  // Magnitude: 15-30% boost in social cohesion, government effectiveness
   186→  // Duration: 12-24 months post-catastrophe onset, exponential decay over 5 years
   187→  if (state.crises?.catastrophe?.active && state.crises.catastrophe.monthsSinceOnset <= 24) {
   188→    const monthsSince = state.crises.catastrophe.monthsSinceOnset;
   189→    const boostMagnitude = 0.20; // 20% boost (mid-range of 15-30% research-backed range)
   190→    const boost = boostMagnitude * Math.exp(-monthsSince / 12); // Exponential decay
   191→
   192→    // Apply cooperation boost to social cohesion
   193→    social.socialCohesion = Math.min(1, social.socialCohesion + boost);
   194→
   195→    // Apply emergency mobilization boost to government effectiveness
   196→    state.government.legitimacy = Math.min(1, state.government.legitimacy + boost * 1.5);
   197→
   198→    // Boost collective action willingness (creates window for breakthrough deployment)
   199→    state.society.coordinationCapacity = Math.min(1, state.society.coordinationCapacity + boost * 2.0);
   200→
   201→    // Log cooperation boost (only during first month for clarity)
   202→    if (monthsSince === 0) {
   203→      try {
   204→        console.log(`\n  🤝 DISASTER COOPERATION BOOST ACTIVATED (Month ${state.currentMonth})`);
   205→        console.log(`     Catastrophe type: ${state.crises.catastrophe.type}`);
   206→        console.log(`     Boost magnitude: +${(boost * 100).toFixed(1)}% social cohesion`);
   207→        console.log(`     Window: 0-24 months (acute phase)`);
   208→        console.log(`     Research: Wei et al. (2025), Drury et al. (2019), Zaki & Cikara (2020)\n`);
   209→      } catch (e) { /* Ignore EPIPE */ }
   210→    }
   211→  }
   212→
   213→  // === CULTURAL ADAPTATION (SLOW IMPROVEMENT) ===
   214→  // Base adaptation rate (very slow - generational change)
   215→  let adaptationRate = 0.002; // 0.2% per month (years to shift culture)
   216→  
   217→  // Stage 3+ accelerates adaptation (necessity)
   218→  if (economicStage >= 3.0) {
   219→    adaptationRate += 0.008; // UBI era forces cultural shift
   220→  }
   221→  
   222→  // High unemployment pushes adaptation
   223→  if (unemployment > 0.4) {
   224→    adaptationRate += 0.006; // Crisis forces change
   225→  }
   226→  
   227→  // Education and community programs help
   228→  if (hasEducationPrograms) {
   229→    adaptationRate += 0.005;
   230→  }
   231→  if (hasCommunityPrograms) {
   232→    adaptationRate += 0.004;
   233→  }
   234→  
   235→  // Already-adapted people accelerate others (exponential)
   236→  if (social.culturalAdaptation > 0.3) {
   237→    adaptationRate *= (1 + social.culturalAdaptation); // Positive feedback
   238→  }
   239→  
   240→  // Institutional failure slows adaptation (no coordination)
   241→  if (social.institutionalLegitimacy < 0.3) {
   242→    adaptationRate *= 0.5; // Hard to coordinate without institutions
   243→  }
   244→  
   245→  // Apply cultural adaptation
   246→  const currentAdaptation = isNaN(social.culturalAdaptation) ? 0.2 : social.culturalAdaptation;
   247→  social.culturalAdaptation = Math.max(0, Math.min(1,
   248→    currentAdaptation + adaptationRate
   249→  ));
   250→  
   251→  // === PHASE 1: LÉVY FLIGHT CASCADE CHECKS (Preference Falsification Cascades) ===
   252→  // Research: Kuran (1991) - "Now out of Never" - preference falsification hides dissent
   253→  // Most of the time: gradual change. Rarely: Leipzig 1989 / Arab Spring cascades
   254→  // When latent opposition + info suppression high → cascade potential
   255→
   256→  const qualityOfLife = state.globalMetrics.qualityOfLife;
   257→  const latentOpposition = Math.max(0, 0.6 - qualityOfLife); // High QoL = low opposition
   258→  const informationIntegrity = state.qualityOfLifeSystems.informationIntegrity;
   259→  const pluralisticIgnorance = 1 - informationIntegrity; // Low integrity = people don't know others share their views
   260→
   261→  // Critical juncture detection (high grievance + low info integrity)
   262→  if (latentOpposition > 0.3 && pluralisticIgnorance > 0.5) {
   263→    // Alpha = 1.8: Fat tails (rare cascades like Arab Spring, Leipzig 1989)
   264→    const cascadePotential = levyFlight(ALPHA_PRESETS.SOCIAL, Math.random);
   265→
   266→    if (cascadePotential > 15.0) {
   267→      // Information cascade triggered (one defector reveals hidden opposition)
   268→      const cascadeSize = Math.min(cascadePotential / 100, 0.4); // Max 40% mobilization
   269→
   270→      // Rapid social cohesion increase (people discover they're not alone)
   271→      social.socialCohesion = Math.min(1.0, social.socialCohesion + cascadeSize);
   272→
   273→      // Institutional legitimacy shifts based on government response
   274→      const governmentResponse = state.government.governmentType === 'authoritarian' ? -cascadeSize * 0.5 : cascadeSize * 0.3;
   275→      social.institutionalLegitimacy = Math.max(0, Math.min(1.0, social.institutionalLegitimacy + governmentResponse));
   276→
   277→      console.log(`\n  📢 PREFERENCE FALSIFICATION CASCADE: Kuran mechanism triggered`);
   278→      console.log(`     Latent opposition: ${(latentOpposition * 100).toFixed(1)}%, Pluralistic ignorance: ${(pluralisticIgnorance * 100).toFixed(1)}%`);
   279→      console.log(`     Magnitude: ${cascadePotential.toFixed(2)} → +${(cascadeSize * 100).toFixed(1)}% mobilization`);
   280→      console.log(`     Cascade type: Leipzig 1989 / Arab Spring mechanism (hidden dissent revealed)`);
   281→    }
   282→  }
   283→
   284→  // === CRISIS TRIGGERS ===
   285→  checkSocialCrises(state);
   286→}
   287→
   288→/**
   289→ * Check if social accumulation has crossed crisis thresholds
   290→ * 
   291→ * Crises trigger QoL impacts, social unrest, and potential dystopia transitions.
   292→ */
   293→function checkSocialCrises(state: GameState): void {
   294→  const social = state.socialAccumulation;
   295→  const qol = state.qualityOfLifeSystems;
   296→  
   297→  // MEANING COLLAPSE: Existential despair exceeds 60%
   298→  if (social.meaningCrisisLevel > 0.6 && !social.meaningCollapseActive) {
   299→    social.meaningCollapseActive = true;
   300→    try {
   301→      console.log(`\n😔 MEANING COLLAPSE TRIGGERED (Month ${state.currentMonth})`);
   302→      console.log(`   Meaning Crisis Level: ${(social.meaningCrisisLevel * 100).toFixed(1)}%`);
   303→      console.log(`   Impact: Mental health crisis, suicide epidemic, despair\n`);
   304→    } catch (e) { /* Ignore EPIPE */ }
   305→
   306→    // Severe QoL impacts
   307→    qol.mentalHealth *= 0.65; // 35% drop
   308→    qol.meaningAndPurpose *= 0.4; // 60% drop
   309→    qol.socialConnection *= 0.7; // 30% drop (isolation spirals)
   310→    state.society.trustInAI = Math.max(0, state.society.trustInAI - 0.35); // Blame AI
   311→    state.globalMetrics.qualityOfLife = Math.max(0, state.globalMetrics.qualityOfLife - 0.35);
   312→
   313→    // Population impact: Suicide epidemic (0.1-0.2% casualties initially)
   314→    // SEMI-GLOBAL: Wealthy automated nations (US, EU, Japan, SK, etc.) = ~30% of world
   315→    // 0.5% mortality rate in affected regions (severe suicide spike)
   316→    const { addAcuteCrisisDeaths } = require('./populationDynamics');
   317→    addAcuteCrisisDeaths(state, 0.005, 'Meaning collapse - suicide epidemic (wealthy nations)', 0.30, 'other');
   318→  }
   319→  
   320→  // INSTITUTIONAL FAILURE: Government legitimacy below 30%
   321→  if (social.institutionalLegitimacy < 0.3 && !social.institutionalFailureActive) {
   322→    social.institutionalFailureActive = true;
   323→    try {
   324→      console.log(`\n🏛️  INSTITUTIONAL FAILURE TRIGGERED (Month ${state.currentMonth})`);
   325→      console.log(`   Institutional Legitimacy: ${(social.institutionalLegitimacy * 100).toFixed(1)}%`);
   326→      console.log(`   Impact: Governance collapse, potential authoritarian takeover\n`);
   327→    } catch (e) { /* Ignore EPIPE */ }
   328→
   329→    // Critical QoL impacts
   330→    qol.politicalFreedom *= 0.6; // 40% drop (power vacuum)
   331→    qol.autonomy *= 0.7; // 30% drop
   332→    state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - 0.6);
   333→    state.government.legitimacy = Math.min(0.25, state.government.legitimacy); // Floor legitimacy
   334→
   335→    // Population impact: State collapse causes chaos, riots, food distribution failures (0.1-0.3% casualties)
   336→    // REGIONAL: Specific failing state (Somalia, Venezuela, etc.) = ~5% of world
   337→    // 4% mortality rate in collapsed state (severe chaos, riots, starvation)
   338→    const { addAcuteCrisisDeaths } = require('./populationDynamics');
   339→    addAcuteCrisisDeaths(state, 0.04, 'Institutional failure - state collapse chaos (failing state)', 0.05, 'other');
   340→
   341→    // High risk of dystopia transition
   342→    // Government may become authoritarian to restore order
   343→    if (Math.random() < 0.4) {
   344→      state.government.governmentType = 'authoritarian';
   345→      try {
   346→        console.log(`   🚨 Authoritarian takeover in response to chaos\n`);
   347→      } catch (e) { /* Ignore EPIPE */ }
   348→    }
   349→  }
   350→  
   351→  // SOCIAL UNREST: Cohesion below 30%
   352→  if (social.socialCohesion < 0.3 && !social.socialUnrestActive) {
   353→    social.socialUnrestActive = true;
   354→    try {
   355→      console.log(`\n🔥 SOCIAL UNREST TRIGGERED (Month ${state.currentMonth})`);
   356→      console.log(`   Social Cohesion: ${(social.socialCohesion * 100).toFixed(1)}%`);
   357→      console.log(`   Impact: Riots, community breakdown, potential civil conflict\n`);
   358→    } catch (e) { /* Ignore EPIPE */ }
   359→
   360→    // Severe QoL impacts
   361→    qol.physicalSafety *= 0.5; // 50% drop (violence)
   362→    qol.communityStrength *= 0.4; // 60% drop
   363→    qol.politicalFreedom *= 0.7; // 30% drop (crackdowns)
   364→    state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - 0.5);
   365→
   366→    // Government responds with control
   367→    state.government.controlDesire = Math.min(1, state.government.controlDesire + 0.3);
   368→    state.government.structuralChoices.surveillanceLevel = Math.min(1,
   369→      state.government.structuralChoices.surveillanceLevel + 0.2
   370→    );
   371→
   372→    // Population impact: Riots and civil violence (0.2-0.5% casualties)
   373→    // REGIONAL: Unstable regions (MENA, parts of Africa/Latin America) = ~10% of world
   374→    // 3% mortality rate in unrest regions (riots, clashes are deadly)
   375→    const { addAcuteCrisisDeaths } = require('./populationDynamics');
   376→    addAcuteCrisisDeaths(state, 0.03, 'Social unrest - riots/civil violence (unstable regions)', 0.10, 'other');
   377→  }
   378→  
   379→  // === ONGOING CRISIS IMPACTS ===
   380→  // Once triggered, crises continue to degrade society
   381→  
   382→  // Calculate cascading failure multiplier (counts crises across ALL systems)
   383→  const cascadeMultiplier = calculateCascadingFailureMultiplier(state);
   384→  
   385→  if (social.meaningCollapseActive) {
   386→    // Ongoing despair
   387→    qol.mentalHealth = Math.max(0, qol.mentalHealth - 0.012 * cascadeMultiplier);
   388→    qol.meaningAndPurpose = Math.max(0, qol.meaningAndPurpose - 0.015 * cascadeMultiplier);
   389→  }
   390→  
   391→  if (social.institutionalFailureActive) {
   392→    // Ongoing governance failure
   393→    qol.politicalFreedom = Math.max(0, qol.politicalFreedom - 0.010 * cascadeMultiplier);
   394→    state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - 0.012 * cascadeMultiplier);
   395→  }
   396→  
   397→  if (social.socialUnrestActive) {
   398→    // Ongoing violence and breakdown
   399→    qol.physicalSafety = Math.max(0, qol.physicalSafety - 0.015 * cascadeMultiplier);
   400→    qol.communityStrength = Math.max(0, qol.communityStrength - 0.010 * cascadeMultiplier);
   401→  }
   402→}
   403→
   404→/**
   405→ * Get social sustainability score (0-1)
   406→ * 
   407→ * Used by Golden Age → Utopia transition logic.
   408→ * Returns how socially stable and adapted the society is.
   409→ */
   410→export function getSocialSustainability(social: SocialAccumulation): number {
   411→  // Inverse meaning crisis (low crisis = good)
   412→  const meaningScore = 1 - social.meaningCrisisLevel;
   413→  
   414→  // Institutional legitimacy (high = good)
   415→  const institutionScore = social.institutionalLegitimacy;
   416→  
   417→  // Social cohesion (high = good)
   418→  const cohesionScore = social.socialCohesion;
   419→  
   420→  // Cultural adaptation (high = good)
   421→  const adaptationScore = social.culturalAdaptation;
   422→  
   423→  // Weighted average (meaning and cohesion most critical)
   424→  return (meaningScore * 0.3 + institutionScore * 0.25 + cohesionScore * 0.3 + adaptationScore * 0.15);
   425→}
   426→
   427→/**
   428→ * Check if any social crisis would block Utopia
   429→ * 
   430→ * Utopia requires social stability and cultural adaptation, not just material prosperity.
   431→ */
   432→export function hasSocialCrisis(social: SocialAccumulation): boolean {
   433→  return social.meaningCollapseActive || 
   434→         social.institutionalFailureActive || 
   435→         social.socialUnrestActive;
   436→}
   437→
   438→/**
   439→ * Get trust in AI derived from paranoia level
   440→ * 
   441→ * Phase 2F+ Paranoia System: Trust is now calculated from paranoia, not stored directly.
   442→ * This ensures trust can recover as paranoia decays, enabling Cognitive Spiral activation.
   443→ * 
   444→ * Formula: trust = 1.0 - (paranoia * 0.75)
   445→ * Bounds: [0.20, 0.95] - Even max paranoia leaves 20% trust, even zero paranoia caps at 95%
   446→ * 
   447→ * @param society - Human society agent with paranoia level
   448→ * @returns Trust level [0.20, 0.95]
   449→ */
   450→/**
   451→ * Get trust in AI for general social dynamics (population-weighted)
   452→ * Used for: social cohesion, protests, public sentiment
   453→ */
   454→export function getTrustInAI(society: HumanSocietyAgent): number {
   455→  const paranoia = society.paranoiaLevel ?? 0.15; // Default to 15% baseline paranoia
   456→  const trustFromParanoia = 1.0 - paranoia * 0.75;
   457→  
   458→  // Floor: Even 100% paranoia leaves 20% trust (some people always believe)
   459→  // Ceiling: Even 0% paranoia caps at 95% trust (healthy skepticism remains)
   460→  return Math.max(0.20, Math.min(0.95, trustFromParanoia));
   461→}
   462→
   463→/**
   464→ * Get trust in AI for policy decisions (power-weighted)
   465→ * P2.3 UPDATE (Oct 16, 2025): Uses power-weighted trust when segments active
   466→ * 
   467→ * Used for: Government policy decisions, regulatory actions
   468→ * Reflects reality: Elites have disproportionate influence over policy
   469→ * 
   470→ * Research:
   471→ * - Gilens & Page (2014, Perspectives on Politics): Economic elites dominate US policy
   472→ * - Bartels (2008, Unequal Democracy): Income disparity in political influence 3:1 ratio
   473→ * - Winters & Page (2009): Oligarchic political influence in democracies
   474→ * 
