   474→/**
   475→ * Check if Utopia conditions are met
   476→ * Utopia requires: 3+ spirals sustained for 12+ months + no active crises
   477→ */
   478→export function canDeclareUtopia(state: GameState): { can: boolean; reason: string; spiralCount: number } {
   479→  const spirals = state.upwardSpirals;
   480→  const qolSystems = state.qualityOfLifeSystems;
   481→  
   482→  // Count sustained spirals (active for 12+ months)
   483→  const sustainedSpirals = [
   484→    spirals.abundance,
