   486→    spirals.democratic,
   487→    spirals.scientific,
   488→    spirals.meaning,
   489→    spirals.ecological
   490→  ].filter(s => s.active && s.monthsActive >= 12);
   491→  
   492→  const sustainedCount = sustainedSpirals.length;
   493→  
   494→  // Need 3+ sustained spirals
   495→  if (sustainedCount < 3) {
   496→    return {
   497→      can: false,
   498→      reason: `Only ${sustainedCount} sustained spirals (need 3+). Active spirals: ${getActiveSpiralNames(spirals).join(', ')}`,
   499→      spiralCount: sustainedCount
   500→    };
   501→  }
   502→  
   503→  // NEW (Oct 12, 2025): Check survival fundamentals
   504→  // Utopia requires ALL survival needs met globally
   505→  // Research: Can't have utopia if people are starving/dying regardless of other metrics
   506→  const survival = qolSystems.survivalFundamentals;
   507→  if (survival) {
   508→    if (survival.foodSecurity < 0.7) {
   509→      return {
   510→        can: false,
   511→        reason: `Food insecurity (${(survival.foodSecurity * 100).toFixed(0)}% < 70% threshold)`,
   512→        spiralCount: sustainedCount
   513→      };
   514→    }
   515→    if (survival.waterSecurity < 0.7) {
   516→      return {
   517→        can: false,
   518→        reason: `Water insecurity (${(survival.waterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   519→        spiralCount: sustainedCount
   520→      };
   521→    }
   522→    if (survival.thermalHabitability < 0.7) {
   523→      return {
   524→        can: false,
   525→        reason: `Thermal uninhabitability (${(survival.thermalHabitability * 100).toFixed(0)}% habitable < 70% threshold)`,
   526→        spiralCount: sustainedCount
   527→      };
   528→    }
   529→    if (survival.shelterSecurity < 0.7) {
   530→      return {
   531→        can: false,
   532→        reason: `Shelter insecurity (${(survival.shelterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   533→        spiralCount: sustainedCount
