   535→    }
   536→  }
   537→  
   538→  // NEW (Oct 12, 2025): Check distribution metrics
   539→  // Utopia requires reasonable equality - can't have "Elysium" scenario
   540→  // Research: Gini >0.40 = problematic inequality (Wilkinson & Pickett)
   541→  const distribution = qolSystems.distribution;
   542→  if (distribution) {
   543→    if (distribution.globalGini > 0.40) {
   544→      return {
   545→        can: false,
   546→        reason: `High inequality (Gini ${(distribution.globalGini).toFixed(2)} > 0.40 threshold)`,
   547→        spiralCount: sustainedCount
   548→      };
   549→    }
