   598→  
   599→  // Success! All conditions met
   600→  return {
   601→    can: true,
   602→    reason: `${sustainedCount} upward spirals sustained for 12+ months: ${getSustainedSpiralNames(spirals).join(', ')}`,
   603→    spiralCount: sustainedCount
